insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'thermo-kinetics-equilibrium', 'Reaction rate', 'The reaction rate or rate of reaction is the speed at which a chemical reaction takes place, defined as proportional to the increase in the concentration of a product per unit time or to the decrease in the concentration of a reactant per unit time. Reaction rates can vary dramatically. For example, the oxidative rusting of iron under Earth''s atmosphere is a slow reaction that can take many years, but the combustion of cellulose in fire is a reaction that takes place in fractions of a second. For most reactions, the rate decreases as the reaction proceeds. A reaction''s rate can be determined by measuring the changes in concentration over time. Chemical kinetics is the part of physical chemistry that concerns how rates of chemical reactions are measured and predicted, and how reaction-rate data can be used to deduce probable reaction mechanisms. The concepts of chemical kinetics are applied in many disciplines, such as chemical engineering, enzymology and environmental engineering.', 'Wikipedia: Reaction rate', 'https://en.wikipedia.org/w/index.php?title=Reaction_rate&oldid=1378663025', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'thermo-kinetics-equilibrium' and body = 'The reaction rate or rate of reaction is the speed at which a chemical reaction takes place, defined as proportional to the increase in the concentration of a product per unit time or to the decrease in the concentration of a reactant per unit time. Reaction rates can vary dramatically. For example, the oxidative rusting of iron under Earth''s atmosphere is a slow reaction that can take many years, but the combustion of cellulose in fire is a reaction that takes place in fractions of a second. For most reactions, the rate decreases as the reaction proceeds. A reaction''s rate can be determined by measuring the changes in concentration over time. Chemical kinetics is the part of physical chemistry that concerns how rates of chemical reactions are measured and predicted, and how reaction-rate data can be used to deduce probable reaction mechanisms. The concepts of chemical kinetics are applied in many disciplines, such as chemical engineering, enzymology and environmental engineering.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'thermo-kinetics-equilibrium', 'Reaction rate: Formal definition', 'The lowercase letters (a, b, p, and q) represent stoichiometric coefficients, while the capital letters represent the reactants (A and B) and the products (P and Q). for a chemical reaction occurring in a closed system at constant volume, without a build-up of reaction intermediates, is defined as where [X] denotes the concentration of the substance X= {A, B, P, Q}. The reaction rate thus defined has the units of mol/(L⋅s). The rate of a reaction is always positive. A negative sign is present to indicate that the reactant concentration is decreasing. The IUPAC recommends that the unit of time should always be the second. The rate of reaction differs from the rate of increase of concentration of a product P by a constant factor (the reciprocal of its stoichiometric number) and for a reactant A by minus the reciprocal of the stoichiometric number. The stoichiometric numbers are included so that the defined rate is independent of which reactant or product species is chosen for measurement. For example, if a = 1 and b = 3, then B is consumed three times more rapidly than A, but is uniquely defined. An additional advantage of this definition is that for an elementary and irreversible reaction,', 'Wikipedia: Reaction rate', 'https://en.wikipedia.org/w/index.php?title=Reaction_rate&oldid=1378663025', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'thermo-kinetics-equilibrium' and body = 'The lowercase letters (a, b, p, and q) represent stoichiometric coefficients, while the capital letters represent the reactants (A and B) and the products (P and Q). for a chemical reaction occurring in a closed system at constant volume, without a build-up of reaction intermediates, is defined as where [X] denotes the concentration of the substance X= {A, B, P, Q}. The reaction rate thus defined has the units of mol/(L⋅s). The rate of a reaction is always positive. A negative sign is present to indicate that the reactant concentration is decreasing. The IUPAC recommends that the unit of time should always be the second. The rate of reaction differs from the rate of increase of concentration of a product P by a constant factor (the reciprocal of its stoichiometric number) and for a reactant A by minus the reciprocal of the stoichiometric number. The stoichiometric numbers are included so that the defined rate is independent of which reactant or product species is chosen for measurement. For example, if a = 1 and b = 3, then B is consumed three times more rapidly than A, but is uniquely defined. An additional advantage of this definition is that for an elementary and irreversible reaction,');
